CREATE TABLE CORE_REL_OCTOPUS.T_INBOUND_DISPO_ORDER_2 (
   inbound_dispo_order_sid             NUMBER          NOT NULL COMMENT 'The unique identifier (surrogate key) for the disposition.',
   dwh_valid_from_tmsp                 TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record became valid.',
   dwh_valid_to_tmsp                   TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was no longer valid.',
   dwh_valid_fg                        BOOLEAN         NOT NULL COMMENT 'An indicator showing the current record in history.',
   dispo_nr                            VARCHAR(20)     COMMENT 'A numeric or alphanumeric value which identifies the disposition for the business.',
   bus_country_cd                      VARCHAR(2)      COMMENT 'A two-character code according to the business definition of Kaufland or Lidl.',
   is_recycled_fg                      BOOLEAN         COMMENT 'The flag sorts out a new DISPOID (ELM), which includes the same information as the old DISPOID. Therefore the old DISPOID is not included in the factual communication.',
   logistic_type_cd                    VARCHAR(20)     COMMENT 'The code for the type of the logistic, e.g. Direct- or Collective logistics.',
   logistic_type_id                    NUMBER          COMMENT 'ID for logistic_temp_cd. e.g. KT has ID 24, TK 25. ',
   logistic_temp_cd                    VARCHAR(20)     COMMENT 'The code for the type of the temperature zone, e.g. TK, TL.',
   direct_dispo_fg                     BOOLEAN         COMMENT 'Flag for a direct dispo. Whether its a direct delivery from the supplier_2 to the Lidl regional distribution center (Direktlauf).',
   kombi_logistic_fg                   BOOLEAN         COMMENT 'The flag sorts out combi logistics, which are excluded in the factual communication.',
   dispo_order_status_cd               VARCHAR(20)     COMMENT 'The code for the status_2 of the disposition (e.g. initialized, approved, sent)',
   dispo_year                          NUMBER          COMMENT 'The dispo year.',
   dispo_week                          NUMBER          COMMENT 'The dispo week.',
   dispo_scheme_descr                  VARCHAR(100)    COMMENT 'LogType + shortcut for cross dock+ cross dock name + target country.',
   order_day_seq                       NUMBER          COMMENT 'An indicator showing which order day within the dispo week.',
   version_nr                          NUMBER          COMMENT 'A number showing the version of the disposition. It increases with each change.',
   main_crossdock_site_sid             NUMBER          COMMENT 'The unique identifier (surrogate key) for the cross-dock that is used in case of Collective-Logistics.',
   dispo_order_delivery_range_cd       VARCHAR(20)     COMMENT 'The code for the delivery range, i.e. whether it is a day based or week based disposition.',
   delivery_from_dt                    DATE            COMMENT 'In case of Collective-Logistics it contains the minimum date of the delivery.',
   delivery_to_dt                      DATE            COMMENT 'In case of Collective-Logistics it contains the maximum date of the delivery.',
   dwh_created_tmsp                    TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
   dwh_updated_tmsp                    TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was last updated.',   
   CONSTRAINT PK_T_INBOUND_DISPO_ORDER PRIMARY KEY (inbound_dispo_order_sid, dwh_valid_from_tmsp) NOT ENFORCED 
)  COMMENT = 'The entity contains head information for all inbound logistics dispositions.';
